datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model User {
  id           Int           @id @default(autoincrement())
  transactions Transaction[]
}

model Transaction {
  id          Int      @id @default(autoincrement())
  date        DateTime
  amount      Float
  type        String
  category    String
  description String
  user        User     @relation(fields: [userId], references: [id])
  userId      Int
}

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { getAnalytics } from "./src/queries" with { type: "ref" };
import { createTransaction } from "./src/actions" with { type: "ref" };
import { seedData } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "financial-analytics",
  title: "Financial Analytics Dashboard",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  db: {
    seeds: [seedData],
  },
  spec: [
    route("MainRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getAnalytics, { entities: ["Transaction"] }),
    action(createTransaction, { entities: ["Transaction"] }),
  ],
});

import type { GetAnalytics } from "wasp/server/operations";

type AnalyticsInput = {
  startDate: string;
  endDate: string;
  resolution: "day" | "week" | "month";
};

type TimeSeriesRow = {
  date: string;
  income: number;
  expense: number;
  net: number;
};

type CategoryBreakdownRow = {
  category: string;
  amount: number;
  type: "INCOME" | "EXPENSE";
};

type AnalyticsOutput = {
  timeSeries: TimeSeriesRow[];
  categoryBreakdown: CategoryBreakdownRow[];
  summary: {
    totalIncome: number;
    totalExpense: number;
    netSavings: number;
    savingsRate: number;
  };
};

export const getAnalytics: GetAnalytics<AnalyticsInput, AnalyticsOutput> = async (
  { startDate, endDate, resolution },
  context
) => {
  const userId = context.user?.id;
  if (!userId) {
    throw new Error("Not authenticated");
  }

  // Build the date format expression based on resolution
  let dateExpr: string;
  switch (resolution) {
    case "day":
      dateExpr = "strftime('%Y-%m-%d', date)";
      break;
    case "week":
      // SQLite week: %W gives week number (00-53), starting on Monday
      dateExpr = "strftime('%Y-W%W', date)";
      break;
    case "month":
      dateExpr = "strftime('%Y-%m', date)";
      break;
  }

  const timeSeriesQuery = `
    SELECT
      ${dateExpr} as date,
      SUM(CASE WHEN type = 'INCOME' THEN amount ELSE 0 END) as income,
      SUM(CASE WHEN type = 'EXPENSE' THEN amount ELSE 0 END) as expense,
      SUM(CASE WHEN type = 'INCOME' THEN amount ELSE -amount END) as net
    FROM Transaction
    WHERE userId = ?
      AND date >= ?
      AND date <= ?
    GROUP BY date
    ORDER BY date ASC
  `;

  const categoryBreakdownQuery = `
    SELECT
      category,
      SUM(amount) as amount,
      type
    FROM Transaction
    WHERE userId = ?
      AND date >= ?
      AND date <= ?
    GROUP BY category, type
    ORDER BY type, amount DESC
  `;

  const summaryQuery = `
    SELECT
      SUM(CASE WHEN type = 'INCOME' THEN amount ELSE 0 END) as totalIncome,
      SUM(CASE WHEN type = 'EXPENSE' THEN amount ELSE 0 END) as totalExpense
    FROM Transaction
    WHERE userId = ?
      AND date >= ?
      AND date <= ?
  `;

  const startDateStr = startDate + "T00:00:00.000Z";
  const endDateStr = endDate + "T23:59:59.999Z";

  const timeSeriesResult = await context.entities.Transaction.$queryRawUnsafe(
    timeSeriesQuery,
    userId,
    startDateStr,
    endDateStr
  ) as TimeSeriesRow[];

  const categoryBreakdownResult = await context.entities.Transaction.$queryRawUnsafe(
    categoryBreakdownQuery,
    userId,
    startDateStr,
    endDateStr
  ) as CategoryBreakdownRow[];

  const summaryResult = await context.entities.Transaction.$queryRawUnsafe(
    summaryQuery,
    userId,
    startDateStr,
    endDateStr
  ) as Array<{ totalIncome: number | null; totalExpense: number | null }>;

  const totalIncome = summaryResult[0]?.totalIncome ?? 0;
  const totalExpense = summaryResult[0]?.totalExpense ?? 0;
  const netSavings = totalIncome - totalExpense;
  const savingsRate = totalIncome > 0 ? (netSavings / totalIncome) * 100 : 0;

  return {
    timeSeries: timeSeriesResult,
    categoryBreakdown: categoryBreakdownResult,
    summary: {
      totalIncome,
      totalExpense,
      netSavings,
      savingsRate,
    },
  };
};

import type { CreateTransaction } from "wasp/server/operations";

type CreateTransactionInput = {
  date: string;
  amount: number;
  type: "INCOME" | "EXPENSE";
  category: string;
  description: string;
};

export const createTransaction: CreateTransaction<CreateTransactionInput, unknown> = async (
  input,
  context
) => {
  const userId = context.user?.id;
  if (!userId) {
    throw new Error("Not authenticated");
  }

  const transaction = await context.entities.Transaction.create({
    data: {
      date: new Date(input.date),
      amount: input.amount,
      type: input.type,
      category: input.category,
      description: input.description,
      userId,
    },
  });

  return transaction;
};

import type { DbSeedFn } from "wasp/server";

export const seedData: DbSeedFn = async (prisma) => {
  // Create test user
  const user = await prisma.user.create({
    data: {
      id: 1,
    },
  });

  // Seed transactions
  const transactions = [
    {
      date: new Date("2026-07-01"),
      amount: 5000.0,
      type: "INCOME",
      category: "Sales",
      description: "Project payment",
      userId: user.id,
    },
    {
      date: new Date("2026-07-15"),
      amount: 1200.0,
      type: "EXPENSE",
      category: "Marketing",
      description: "Ad campaign",
      userId: user.id,
